#include "SamplePreview.h"
static void testSamplePreview(const File& root,Assets& assets){
    Sample source;source.sampleRate=48000;source.audio.setSize(2,9600);
    for(int i=0;i<9600;++i){source.audio.setSample(0,i,i/10000.f);source.audio.setSample(1,i,-i/10000.f);}
    auto song=emptyProject();song.bpm=120;
    auto run=[&](double bpm,bool repeat,double start,double end,int frames,int block=512){
        auto e=makeEngine(song,assets,root);e->stop();expect(e->preview(&source,start,end,1,bpm,repeat),"valid sample audition enters bounded queue");
        AudioBuffer<float> result(2,frames);for(int i=0;i<frames;i+=block)e->render(result.getWritePointer(0,i),result.getWritePointer(1,i),jmin(block,frames-i));return result;
    };
    auto original=run(0,false,0,0,4800);expect(std::abs(original.getSample(0,1000)-.1f)<1e-7&&original.getSample(1,1000)==-original.getSample(0,1000),"original preview retains exact source speed and stereo separation");
    auto fast=run(60,false,0,0,4801);expect(std::abs(fast.getSample(0,1000)-.2f)<1e-7&&fast.getSample(0,4800)==0,"120 BPM song previews 60 BPM source at twice speed and stops at source end");
    auto slow=run(240,false,0,0,4800);expect(std::abs(slow.getSample(0,1001)-.05005f)<1e-7,"half speed interpolates fractional source positions");
    auto loop=run(60,true,.01,.02,6000,127);bool correct=true;for(int i=0;i<6000;++i)correct&=std::abs(loop.getSample(0,i)-(480+(i*2)%480)/10000.f)<1e-7;expect(correct,"trimmed repeated preview wraps without silence or reading outside the chosen range");
    auto loop2=run(60,true,.01,.02,6000,1024);bool same=true;for(int c=0;c<2;++c)for(int i=0;i<6000;++i)same&=loop.getSample(c,i)==loop2.getSample(c,i);expect(same,"tempo audition output is independent of callback size");
    auto e=makeEngine(song,assets,root);e->stop();AudioBuffer<float> block(2,1024);expect(e->preview(&source,0,0,1,60,true),"tempo follow fixture queues");e->render(block.getWritePointer(0),block.getWritePointer(1),100);song.bpm=60;String warnings;compilePlayback(song,assets,root,e->exchange.beginWrite(),warnings);e->exchange.publish();e->render(block.getWritePointer(0),block.getWritePointer(1),100);expect(std::abs(block.getSample(0,0)-.02f)<1e-7&&std::abs(block.getSample(0,99)-.0299f)<1e-7,"active preview follows a tempo publication without restarting or changing source position");
    e->cancelPreview();e->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(!e->previewPlaying.load()&&block.getMagnitude(0,0,512)==0,"cancel stops repeated audition through the generation barrier");
    auto q=makeEngine(song,assets,root);song.bpm=120;compilePlayback(song,assets,root,q->exchange.beginWrite(),warnings);q->exchange.publish();q->seekRequested.store(.25);q->render(block.getWritePointer(0),block.getWritePointer(1),0);
    Sample constant;constant.sampleRate=48000;constant.audio.setSize(2,48000);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)constant.audio.setSample(c,i,.3f);
    expect(q->preview(&constant,0,0,1,120,true,true),"quantized preview queues while song is running");AudioBuffer<float> aligned(2,18002);q->render(aligned.getWritePointer(0),aligned.getWritePointer(1),18002);expect(aligned.getMagnitude(0,0,18000)==0&&std::abs(aligned.getSample(0,18000)-.3f)<1e-7,"synced preview waits precisely for the next project beat");
    q->stop();q->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(!q->previewPlaying.load()&&block.getMagnitude(0,0,512)==0,"transport stop cancels pending and repeating audition");
    expect(q->preview(&constant,0,0,1,120,true)&&q->preview(&source,0,0,1,120,true),"two sources can be queued without allocating in render");q->cancelPreview();q->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(!q->previewPlaying.load(),"generation cancellation rejects all older queued sources");
    expect(!q->preview(&source,0,0,1,19)&&!q->preview(&source,0,0,1,401)&&!q->preview(&source,0,0,1,std::numeric_limits<double>::infinity()),"invalid and nonfinite source tempos are rejected before publication");
    expect(!q->preview(&source,-1,0)&&!q->preview(&source,.1,.05)&&!q->preview(&source,0,.3)&&!q->preview(&source,std::numeric_limits<double>::quiet_NaN()),"invalid preview ranges fail before reaching the callback");
    q->prepare(44100);expect(q->preview(&source,0,0,1,120),"source-rate conversion preview queues");q->render(block.getWritePointer(0),block.getWritePointer(1),442);expect(std::abs(block.getSample(0,441)-.048f)<1e-6,"preview speed includes device/source sample-rate conversion");
    auto folder=root.getChildFile("preview-prefs");folder.createDirectory();auto file=folder.getChildFile("source.wav"),catalog=folder.getChildFile("preview.json");file.replaceWithText("fixture");catalog.deleteFile();SamplePreviewOptions options;
    expect(loadSamplePreview(catalog,file,options).wasOk()&&options==SamplePreviewOptions{},"missing preview catalog defaults to original speed and one pass");
    options={true,true,97.5};expect(saveSamplePreview(catalog,file,options,samplePreviewToken(catalog),samplePreviewStamp(file)).wasOk(),"source-specific tempo/repeat preferences save atomically");SamplePreviewOptions loaded;expect(loadSamplePreview(catalog,file,loaded).wasOk()&&loaded==options,"fractional source tempo and modes survive reload");auto token=samplePreviewToken(catalog),stamp=samplePreviewStamp(file);
    auto changed=options;changed.sourceBpm=110;expect(saveSamplePreview(catalog,file,changed,"stale",stamp).failed()&&samplePreviewToken(catalog)==token,"stale preference edits retain current catalog bytes");file.appendText("changed");expect(saveSamplePreview(catalog,file,changed,token,stamp).failed()&&samplePreviewToken(catalog)==token,"source replacement rejects an already open configuration");expect(loadSamplePreview(catalog,file,loaded).wasOk()&&loaded==SamplePreviewOptions{},"replaced source never inherits a stale tempo estimate");
    auto before=catalog.loadFileAsString();changed.sourceBpm=std::numeric_limits<double>::quiet_NaN();expect(saveSamplePreview(catalog,file,changed,token,samplePreviewStamp(file)).failed()&&catalog.loadFileAsString()==before,"invalid settings do not change persisted catalog");
    catalog.replaceWithText("{broken");token=samplePreviewToken(catalog);loaded=options;expect(loadSamplePreview(catalog,file,loaded).failed()&&loaded==options,"malformed catalog preserves caller options on failure");expect(saveSamplePreview(catalog,file,options,token,samplePreviewStamp(file)).failed()&&samplePreviewToken(catalog)==token,"corrupt catalog is retained without silent replacement");
    catalog.deleteFile();for(int i=0;i<130;++i){auto f=folder.getChildFile(String(i)+".wav");f.replaceWithText("x");expect(saveSamplePreview(catalog,f,options,samplePreviewToken(catalog),samplePreviewStamp(f)).wasOk(),"bounded audition catalog accepts successive sources");}auto json=JSON::parse(catalog.loadFileAsString());expect(json["sources"].getArray()->size()==128,"preview source preferences evict oldest configuration at 128 entries");
    q->stop();
}
